(()=>{'use strict';
const $=id=>document.getElementById(id),KEY='mooncatch-echo-sync-v1',chapters=['同频起步','月箱供能','数字排雷','一笔月纹','综合遗迹'];
let game,index=0,paused=false,hold=null,repeat=null,pointer=null,anim=0,from=null,started=0,swipe=null;
function progress(){try{const p=JSON.parse(localStorage.getItem(KEY));if(p&&Array.isArray(p.completed)&&p.best)return p}catch{}return {completed:[],best:{}}}
function save(){const p=progress(),id=index+1;if(!p.completed.includes(id))p.completed.push(id);p.completed.sort((a,b)=>a-b);p.best[id]=Math.min(p.best[id]??Infinity,game.state.moves);try{localStorage.setItem(KEY,JSON.stringify(p));parent.MooncatchSaveChanged?.()}catch{$('status').textContent='通关成功，但存档写入失败，请检查存储空间。'}}
function stop(){clearTimeout(hold);clearInterval(repeat);hold=repeat=null;pointer=null;swipe=null}
function choose(i){stop();index=Math.max(0,Math.min(19,i));game=new EchoSync.Game(EchoLevels[index]);paused=false;from=null;for(const d of document.querySelectorAll('dialog'))d.close();$('chapter').textContent=`第 ${Math.floor(index/4)+1} 章 · ${chapters[Math.floor(index/4)]}`;$('title').textContent=`${index+1}. ${game.level.title}`;$('rule').textContent=game.level.rule;update();draw();}
function update(){const s=game.state;$('steps').textContent=`${s.moves} 步 · ${game.level.transform==='mirrorX'?'本体 → / 影子 ←':'两侧同向'}`;$('undo').disabled=!game.history.length;$('check').hidden=s.safe.every(Boolean);$('status').textContent=game.notice||'让两位旅人归航，并完成本关的箱座、排雷与月纹。';for(let i=0;i<2;i++){const b=game.level.boards[i];$('stats'+i).textContent=[b.docks.length?`箱 ${b.docks.filter(n=>s.boxes[i].includes(n)).length}/${b.docks.length}`:'',b.trails.length?`纹 ${s.ink[i].toString(2).replace(/0/g,'').length}/${b.trails.length}`:'',b.cells.length?`雷 ${s.flags[i].length}/${b.mines.length}`:''].filter(Boolean).join(' · ');}}
function step(d){if(paused||document.querySelector('dialog[open]'))return false;const before=EchoSync.copy(game.state),moved=game.step(d);if(moved){from=before;started=performance.now();if(!anim)anim=requestAnimationFrame(paint);finish();}update();if(!moved)draw();return moved;}
function finish(){if(game.won){stop();save();$('result').textContent=`第 ${index+1} 关完成 · ${game.state.moves} 步。可以撤销后研究另一条路线。`;$('next').textContent=index===19?'返回关卡':'下一关';$('victory').showModal();}}
function paint(t){anim=0;draw(Math.min(1,(t-started)/110));if(from&&t-started<110)anim=requestAnimationFrame(paint);else from=null;}
function draw(f=1){if(!game)return;for(let i=0;i<2;i++){
 const b=game.level.boards[i],s=game.state,c=$('board'+i),size=Math.max(140,Math.round(c.getBoundingClientRect().width)),ratio=Math.min(devicePixelRatio||1,2);if(c.width!==Math.round(size*ratio)){c.width=c.height=Math.round(size*ratio)}const ctx=c.getContext('2d');if(!ctx)continue;ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,size,size);const u=size/b.w;
 const text=(v,n,color='#d5e6e8',scale=.43)=>{ctx.fillStyle=color;ctx.font=`600 ${u*scale}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(v,(n%b.w+.5)*u,(Math.floor(n/b.w)+.53)*u)};
 for(let n=0;n<b.floor.length;n++){const x=n%b.w*u,y=Math.floor(n/b.w)*u;ctx.fillStyle=b.floor[n]==='#'?'#243846':'#0d202d';ctx.fillRect(x+1,y+1,u-2,u-2);if(b.floor[n]==='#')continue;
 if(b.trailIndex.has(n)){const used=s.ink[i]&(1<<b.trailIndex.get(n));ctx.strokeStyle=used?'#426676':'#a6cdd4';ctx.lineWidth=2;ctx.strokeRect(x+u*.22,y+u*.22,u*.56,u*.56);if(used)text('·',n,'#93adb7');}
 if(n===b.goal)text('◇',n,'#9ce2d0',.75);
 if(b.docks.includes(n))text('▣',n,'#e3c489',.66);
 const plate=(b.plates||[]).find(p=>EchoSync.at(p.at,b.w)===n);if(plate)text(plate.id,n,'#eac889',.5);
 const gate=b.gate.find(g=>g.pos===n);if(gate){ctx.strokeStyle=EchoSync.openGate(game.level,s,gate)?'#8fe3c1':'#d69489';ctx.lineWidth=3;ctx.strokeRect(x+4,y+4,u-8,u-8);text(gate.id,n,ctx.strokeStyle);}
 const clue=b.clues.find(c=>c.pos===n);if(clue)text(String(clue.count),n,['#4b737d','#9eccec','#9ed8ad','#e6b690'][Math.min(clue.count,3)],.38);
 if(b.cells.includes(n)){ctx.fillStyle=s.safe[i]?'#183b3c':'#304451';ctx.fillRect(x+3,y+3,u-6,u-6);text(s.flags[i].includes(n)?'⚑':s.safe[i]?'·':'?',n,s.flags[i].includes(n)?'#f1bd9a':'#d5e6e8');}
 }
 for(const n of s.boxes[i]){const x=n%b.w*u,y=Math.floor(n/b.w)*u;ctx.fillStyle=b.docks.includes(n)?'#b4d1a0':'#c2a778';ctx.fillRect(x+u*.22,y+u*.22,u*.56,u*.56);text('□',n,'#293e3c',.4);}
 const a=from?.p[i]??s.p[i],n=s.p[i],x=((a%b.w)*(1-f)+(n%b.w)*f+.5)*u,y=(Math.floor(a/b.w)*(1-f)+Math.floor(n/b.w)*f+.5)*u;ctx.fillStyle=i?'#adbbf1':'#f2d69c';ctx.beginPath();ctx.arc(x,y,u*.25,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#f6faf8';ctx.lineWidth=1.5;ctx.stroke();
 // Keep every deduction visible even when a traveller or box covers its cell.
 for(const clue of b.clues){const x=(clue.pos%b.w+.16)*u,y=(Math.floor(clue.pos/b.w)+.18)*u;ctx.fillStyle='#0b1a26';ctx.fillRect(x-u*.14,y-u*.14,u*.3,u*.3);ctx.fillStyle=clue.count?'#e9d6a6':'#93bac2';ctx.font=`700 ${u*.27}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(clue.count),x,y)}
 }}
function menu(){stop();$('victory').close();const p=progress();$('levelgrid').replaceChildren();EchoLevels.forEach((l,i)=>{if(i%4===0){const h=document.createElement('div');h.className='chapter';h.textContent=chapters[i/4];$('levelgrid').append(h)}const b=document.createElement('button');b.textContent=`${p.completed.includes(i+1)?'✓ ':''}${i+1} ${l.title}`;b.className=(i===index?'current ':'')+(p.completed.includes(i+1)?'done':'');b.onclick=()=>choose(i);$('levelgrid').append(b)});$('menu').showModal()}
for(const b of document.querySelectorAll('[data-dir]')){b.onpointerdown=e=>{e.preventDefault();if(pointer!==null||paused)return;pointer=e.pointerId;b.setPointerCapture(e.pointerId);step(b.dataset.dir);if(pointer!==null)hold=setTimeout(()=>{repeat=setInterval(()=>step(b.dataset.dir),150)},280)};b.onpointerup=b.onpointercancel=b.onlostpointercapture=stop;}
for(let i=0;i<2;i++){const c=$('board'+i);c.onpointerdown=e=>{if(paused||swipe)return;c.setPointerCapture(e.pointerId);swipe={x:e.clientX,y:e.clientY,id:e.pointerId}};c.onpointerup=e=>{if(!swipe||e.pointerId!==swipe.id)return;const a=swipe;swipe=null;const dx=e.clientX-a.x,dy=e.clientY-a.y;if(Math.max(Math.abs(dx),Math.abs(dy))>24){step(Math.abs(dx)>Math.abs(dy)?dx>0?'R':'L':dy>0?'D':'U');return}const r=c.getBoundingClientRect(),b=game.level.boards[i],x=Math.floor((e.clientX-r.left)/r.width*b.w),y=Math.floor((e.clientY-r.top)/r.height*b.h);if(game.flag(i,y*b.w+x)){update();draw()}};c.onpointercancel=()=>{swipe=null};}
$('undo').onclick=()=>{stop();from=null;game.undo();update();draw()};$('reset').onclick=()=>choose(index);$('hint').onclick=()=>{stop();$('helpRule').textContent=game.level.rule;$('helpHint').textContent=game.level.hint;$('help').showModal()};$('closeHelp').onclick=()=>{$('help').close()};$('check').onclick=()=>{game.check();update();draw();finish()};$('levels').onclick=menu;$('closeMenu').onclick=()=>{$('menu').close();paused=false};$('next').onclick=()=>index<19?choose(index+1):menu();$('review').onclick=()=>{$('victory').close()};$('pick').onclick=menu;$('home').onclick=()=>{stop();if(parent!==window&&parent.MooncatchSuite)parent.MooncatchSuite.home();else location.href='../index.html'};
addEventListener('keydown',e=>{if(e.repeat)return;const d={ArrowUp:'U',ArrowDown:'D',ArrowLeft:'L',ArrowRight:'R',w:'U',s:'D',a:'L',d:'R'}[e.key];if(d){e.preventDefault();step(d)}else if(e.key==='Escape')menu();else if(e.key==='z')$('undo').click()});
addEventListener('blur',stop);addEventListener('resize',()=>{stop();from=null;draw()});document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();paused=true}else paused=false});
window.MoonEcho={get game(){return game},get index(){return index},choose,step,draw,menu,pause(v=true){stop();paused=v},back(){if($('help').open){$('help').close();return}if($('victory').open){$('victory').close();return}if($('menu').open){$('menu').close();parent.MooncatchSuite?.home();return}menu()}};choose(0);
})();
